def find_base_blocks():
    import itertools

    # We need 5 blocks of size 3 from Z_17, and 1 block {inf, 0, d}
    # The differences from the 5 blocks + {0, d} must cover every non-zero element of Z_17 exactly twice.

    # Let's just search for 5 blocks of size 3 and 1 pair {0, d}
    # such that their differences give each element in {1..16} exactly twice.

    # To avoid symmetry, we can assume the pair is {0, d} where d is in {1..8}.
    # Actually, we can just iterate over all possible 5 blocks and d.

    # Precompute differences for all possible blocks of size 3 in Z_17
    # We can fix the first element of each block to 0 to reduce search space.
    # So blocks are {0, a, b} where 0 < a < b < 17.

    blocks = []
    for a in range(1, 17):
        for b in range(a + 1, 17):
            diffs = [a, 17-a, b, 17-b, b-a, 17-(b-a)]
            blocks.append( ( (0, a, b), diffs ) )

    # We need to choose 5 blocks.
    # Let's use a recursive search.

    def search(idx, current_counts, chosen_blocks):
        if len(chosen_blocks) == 5:
            # Check if the remaining needed differences can be formed by {0, d}
            # We need exactly two elements to have count 1, and the rest count 2.
            # And the two elements must be d and 17-d.
            missing = []
            for i in range(1, 17):
                if current_counts[i] == 1:
                    missing.append(i)
                elif current_counts[i] != 2:
                    return None
            if len(missing) == 2 and missing[0] + missing[1] == 17:
                return chosen_blocks, missing[0]
            return None

        for i in range(idx, len(blocks)):
            blk, diffs = blocks[i]

            # Check if adding these diffs exceeds 2
            ok = True
            for d in diffs:
                if current_counts[d] == 2:
                    ok = False
                    break
            if not ok:
                continue

            for d in diffs:
                current_counts[d] += 1

            res = search(i, current_counts, chosen_blocks + [blk])
            if res: return res

            for d in diffs:
                current_counts[d] -= 1

        return None

    counts = [0] * 17
    res = search(0, counts, [])
    print(res)

find_base_blocks()

def generate_bibd():
    base_blocks = [
        (0, 1, 2),
        (0, 2, 5),
        (0, 3, 8),
        (0, 4, 10),
        (0, 4, 10)
    ]

    blocks = []
    # Points: 0..16 for Z_17, 17 for inf
    for i in range(17):
        for b in base_blocks:
            blocks.append(tuple((x + i) % 17 for x in b))
        blocks.append((17, i, (i + 8) % 17))

    # Create incidence matrix
    matrix = [[0] * 102 for _ in range(18)]
    for j, blk in enumerate(blocks):
        for p in blk:
            matrix[p][j] = 1

    # Verify
    # Row sums
    for i in range(18):
        if sum(matrix[i]) != 17:
            print(f"Row {i} sum is {sum(matrix[i])}")
            return

    # Col sums
    for j in range(102):
        col_sum = sum(matrix[i][j] for i in range(18))
        if col_sum != 3:
            print(f"Col {j} sum is {col_sum}")
            return

    # Inner products
    for i1 in range(18):
        for i2 in range(i1 + 1, 18):
            dot = sum(matrix[i1][j] * matrix[i2][j] for j in range(102))
            if dot != 2:
                print(f"Inner product of {i1} and {i2} is {dot}")
                return

    print("Verification passed!")

    # Print flat list
    flat = []
    for row in matrix:
        flat.extend(row)
    print(flat[:20])

generate_bibd()
